create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,phone text,cpf text,found_by text,role text not null default 'customer' check(role in('customer','admin')),created_at timestamptz default now());
create table if not exists public.site_settings(key text primary key,value text not null default '',updated_by uuid references auth.users(id),updated_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,description text default '',image_url text,sort_order int default 0,active boolean default true,created_at timestamptz default now());
create table if not exists public.site_photos(id uuid primary key default gen_random_uuid(),title text,image_url text not null,storage_path text,sort_order int default 0,active boolean default true,created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_id uuid not null references public.profiles(id),event_date date not null,status text not null default 'Solicitação recebida',payload jsonb not null default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create index if not exists orders_customer_idx on public.orders(customer_id); create index if not exists orders_date_idx on public.orders(event_date);
create sequence if not exists public.order_number_seq;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name,email,found_by) values(new.id,new.raw_user_meta_data->>'full_name',new.email,new.raw_user_meta_data->>'found_by') on conflict(id) do nothing; return new; end;$$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.create_order(p_event_date date,p_payload jsonb,p_customer_name text default '',p_customer_phone text default '') returns table(id uuid,order_number text) language plpgsql security definer set search_path=public as $$declare new_id uuid:=gen_random_uuid(); n bigint; num text; begin if auth.uid() is null then raise exception 'Usuário não autenticado.'; end if; if p_event_date<current_date+7 then raise exception 'Novos pedidos precisam de no mínimo 7 dias de antecedência.'; end if; insert into public.profiles(id,full_name,email,phone) values(auth.uid(),nullif(p_customer_name,''),(select email from auth.users where id=auth.uid()),nullif(p_customer_phone,'')) on conflict(id) do update set full_name=coalesce(nullif(excluded.full_name,''),profiles.full_name),phone=coalesce(nullif(excluded.phone,''),profiles.phone); n:=nextval('public.order_number_seq'); num:='CC-'||extract(year from current_date)::int||'-'||lpad(n::text,4,'0'); insert into public.orders(id,order_number,customer_id,event_date,payload) values(new_id,num,auth.uid(),p_event_date,p_payload); return query select new_id,num; end;$$;
insert into public.site_settings(key,value) values('hero_title','Amor em forma de doces.'),('hero_text','Bolos e doces personalizados feitos para transformar cada celebração em uma memória especial.'),('instagram','@cariocacakery'),('email','Cariocacakery@gmail.com'),('whatsapp','5521986384989') on conflict(key) do nothing;
