insert into public.site_photos(title,image_url,sort_order) values('Docinhos','/assets/docinhos-1.jpg',1),('Docinhos especiais','/assets/docinhos-2.jpg',2);
alter table public.profiles enable row level security; alter table public.site_settings enable row level security; alter table public.categories enable row level security; alter table public.site_photos enable row level security; alter table public.orders enable row level security;
create policy profiles_select on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin()); create policy profiles_insert on public.profiles for insert to authenticated with check(id=auth.uid()); create policy settings_read on public.site_settings for select to anon,authenticated using(true); create policy settings_admin on public.site_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy categories_read on public.categories for select to anon,authenticated using(true); create policy categories_admin on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy photos_read on public.site_photos for select to anon,authenticated using(true); create policy photos_admin on public.site_photos for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy orders_read on public.orders for select to authenticated using(customer_id=auth.uid() or public.is_admin()); create policy orders_insert on public.orders for insert to authenticated with check(customer_id=auth.uid()); create policy orders_admin_update on public.orders for update to authenticated using(public.is_admin()) with check(public.is_admin());
grant execute on function public.create_order(date,jsonb,text,text) to authenticated;
insert into storage.buckets(id,name,public) values('site-media','site-media',true) on conflict(id) do update set public=true;
create policy site_media_read on storage.objects for select to anon,authenticated using(bucket_id='site-media'); create policy site_media_insert on storage.objects for insert to authenticated with check(bucket_id='site-media' and public.is_admin()); create policy site_media_update on storage.objects for update to authenticated using(bucket_id='site-media' and public.is_admin()) with check(bucket_id='site-media' and public.is_admin()); create policy site_media_delete on storage.objects for delete to authenticated using(bucket_id='site-media' and public.is_admin());
